 if($method==='GET'&&$path==='/admin/analytics'){
  require_admin();
  $stats=[];
  $stats['users']=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();
  $stats['movies']=(int)$pdo->query("SELECT COUNT(*) FROM movies WHERE publication_status='published' AND availability='available'")->fetchColumn();
  $stats['subscriptions']=$pdo->query('SELECT status,COUNT(*) total FROM subscriptions GROUP BY status')->fetchAll();
  $stats['billingStatus']=$pdo->query('SELECT status,COUNT(*) total,COALESCE(SUM(amount),0) amount FROM billing_records GROUP BY status')->fetchAll();
  $stats['revenue']=(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM billing_records WHERE status='successful'")->fetchColumn();
  $stats['popularMovies']=$pdo->query("SELECT id,title,view_count,popularity_score FROM movies WHERE publication_status='published' AND availability='available' ORDER BY view_count DESC,popularity_score DESC LIMIT 10")->fetchAll();
  $stats['genres']=$pdo->query("SELECT g.name,COUNT(DISTINCT m.id) total FROM genres g JOIN movie_genres mg ON mg.genre_id=g.id JOIN movies m ON m.id=mg.movie_id WHERE m.publication_status='published' AND m.availability='available' GROUP BY g.id ORDER BY total DESC")->fetchAll();
  $stats['revenueByMonth']=$pdo->query("SELECT DATE_FORMAT(paid_at,'%Y-%m') month,SUM(amount) revenue FROM billing_records WHERE status='successful' AND paid_at>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY month ORDER BY month")->fetchAll();
  $stats['activityByMonth']=$pdo->query("SELECT DATE_FORMAT(viewed_at,'%Y-%m') month,COUNT(*) views,COUNT(DISTINCT user_id) users FROM viewing_history WHERE viewed_at>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY month ORDER BY month")->fetchAll();
  $stats['userRegistrationsByMonth']=$pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) users FROM users WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY month ORDER BY month")->fetchAll();
  $stats['subscriptionsByMonth']=$pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) subscriptions FROM subscriptions WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY month ORDER BY month")->fetchAll();
  $stats['subscriptionChangesByMonth']=$pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) changes,COALESCE(SUM(status='applied'),0) applied FROM subscription_changes WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY month ORDER BY month")->fetchAll();
  respond($stats);
 }
